-- Switch from GENERATED ALWAYS AS IDENTITY to GENERATED BY DEFAULT so Hibernate's
-- @GeneratedValue(strategy = SEQUENCE) can supply ids at INSERT. Hibernate rejects
-- @GeneratedValue(strategy = IDENTITY) on a component of an @IdClass composite
-- ("Identity generation isn't supported for composite ids"), and the events PK is
-- composite by necessity (Postgres native range partitioning requires the partition
-- key inside the PK).
--
-- ALWAYS would refuse the app-supplied id; BY DEFAULT accepts it while keeping the
-- DB-side default in place for any non-JPA writer (raw SQL, COPY backfills, etc.).
-- The auto-created sequence (events_id_seq, per Postgres default naming) is
-- unchanged; @SequenceGenerator on EventEntity references it directly.
ALTER TABLE events ALTER COLUMN id SET GENERATED BY DEFAULT;
